1	package cli
2	
3	import (
4		"regexp"
5		"sort"
6		"strings"
7	)
8	
9	// factScopeCrossCutting marks facts about how work is done (preferences,
10	// workflow) — they apply repo-wide and are noise for a specific technical
11	// lookup. factScopeLocal marks facts tied to code/subsystems (architecture,
12	// constraints) and standing project facts.
13	const (
14		factScopeCrossCutting = "cross-cutting"
15		factScopeLocal        = "local"
16	)
17	
18	// crossCuttingTopLevels are the taxonomy categories that describe ways of
19	// working rather than the code itself.
20	var crossCuttingTopLevels = map[string]struct{}{
21		"preferences": {},
22		"workflow":    {},
23	}
24	
25	// factScope classifies a fact as cross-cutting or local from its taxonomy
26	// paths. A fact is cross-cutting only when every path is a cross-cutting
27	// category; any code/constraint/project path makes it local (the technical
28	// substance wins). This is the scope-tiering signal: separate "how we work"
29	// from "what this code is", so a technical lookup is not buried under generic
30	// preference and workflow facts.
31	func factScope(paths []string) string {
32		if len(paths) == 0 {
33			return factScopeLocal
34		}
35		for _, p := range paths {
36			if _, ok := crossCuttingTopLevels[factTopLevel(p)]; !ok {
37				return factScopeLocal
38			}
39		}
40		return factScopeCrossCutting
41	}
42	
43	// locusIdentifierPattern matches code-identifier-like tokens: backtick spans are
44	// handled separately; this catches dotted paths (settings.Load), file paths
45	// (internal/cli/facts.go), CamelCase, and snake_case identifiers.
46	var locusIdentifierPattern = regexp.MustCompile(`[A-Za-z_][A-Za-z0-9_]*(?:[./][A-Za-z0-9_]+)+|[A-Za-z_]*[a-z][A-Za-z0-9]*[A-Z][A-Za-z0-9_]*|[A-Za-z][A-Za-z0-9]*_[A-Za-z0-9_]+`)
47	
48	// factLocus extracts the set of code identifiers a fact is about — the symbols,
49	// packages, file paths, and refs named in its text (including backtick-quoted
50	// spans). Returned lowercased and deduped. This is the locus signal: it lets
51	// retrieval boost facts that name the same code the query names, and is the
52	// hook for tying facts to the semantic index in a later slice.
53	func factLocus(text string) []string {
54		set := map[string]struct{}{}
55		add := func(tok string) {
56			tok = strings.ToLower(strings.Trim(tok, "`.,;:()[]{}'\""))
57			if len(tok) >= 3 {
58				set[tok] = struct{}{}
59			}
60		}
61		// Backtick-quoted spans are almost always code; take each whitespace token.
62		for _, span := range backtickSpanPattern.FindAllStringSubmatch(text, -1) {
63			for _, tok := range strings.Fields(span[1]) {
64				add(tok)
65			}
66		}
67		for _, tok := range locusIdentifierPattern.FindAllString(text, -1) {
68			add(tok)
69		}
70		out := make([]string, 0, len(set))
71		for tok := range set {
72			out = append(out, tok)
73		}
74		sort.Strings(out)
75		return out
76	}
77	
78	var backtickSpanPattern = regexp.MustCompile("`([^`]+)`")
79	
80	// locusOverlap counts identifiers shared between a query's locus and a fact's
81	// locus — the strength of the "they name the same code" signal.
82	func locusOverlap(queryLocus []string, factText string) int {
83		if len(queryLocus) == 0 {
