				found = id
				break
			}
			end--
		}
		if found < 0 {
			return append(ids, e.unkID) // whole word is [UNK]
		}
		pieces = append(pieces, found)
		start = end
	}
	return append(ids, pieces...)
}

func isCJK(r rune) bool {
	return (r >= 0x4E00 && r <= 0x9FFF) || (r >= 0x3400 && r <= 0x4DBF) ||
		(r >= 0x20000 && r <= 0x2A6DF) || (r >= 0xF900 && r <= 0xFAFF)
