// isBertPunct matches BERT's punctuation set: the ASCII punctuation ranges plus
// any Unicode punctuation category.
func isBertPunct(r rune) bool {
	if (r >= '!' && r <= '/') || (r >= ':' && r <= '@') || (r >= '[' && r <= '`') || (r >= '{' && r <= '~') {
		return true
	}
