271	// judgeCache persists agent relevance verdicts keyed by "<taskID>\x00<factID>"
272	// so judged evals are repeatable and only new (task, fact) pairs cost an agent
273	// call. It makes judge-based A/Bs deterministic across runs.
274	type judgeCache struct {
275		path    string
276		verdict map[string]bool
277		dirty   bool
278	}
