282	func loadJudgeCache(path string) *judgeCache {
283		c := &judgeCache{path: path, verdict: map[string]bool{}}
284		if strings.TrimSpace(path) == "" {
285			return c
286		}
287		if data, err := os.ReadFile(path); err == nil {
288			_ = json.Unmarshal(data, &c.verdict)
289		}
