import (
	"math"
	"os"
	"sort"
	"strconv"
)

// fusionConfig parameterizes the Reciprocal Rank Fusion of the lexical and
// semantic lists.
//
//   - k0 is the canonical RRF constant; smaller sharpens the influence of each
//     list's top ranks (a relevant fact high in the semantic list contributes
//     more), larger flattens it.
//   - wLex / wSem weight the two lists. Raising wSem lets a term-disjoint but
//     semantically-near fact outrank a weak lexical match — the recall lever.
//
// Defaults are the principled starting point (canonical k0=60, equal weight).
// They are overridable from the environment so the fusion can be A/B-swept with
// eval-compare without recompiling per cell; production keeps the defaults
// unless a swept config is promoted here on measured, per-repo-consistent
// evidence.
type fusionConfig struct {
	k0   float64
	wLex float64
	wSem float64
}

func defaultFusionConfig() fusionConfig {
	c := fusionConfig{k0: 60.0, wLex: 1.0, wSem: 1.0}
	if v, err := strconv.ParseFloat(os.Getenv("ENTIRE_FACTS_RRF_K0"), 64); err == nil && v > 0 {
		c.k0 = v
	}
	if v, err := strconv.ParseFloat(os.Getenv("ENTIRE_FACTS_RRF_WLEX"), 64); err == nil && v >= 0 {
		c.wLex = v
	}
	if v, err := strconv.ParseFloat(os.Getenv("ENTIRE_FACTS_RRF_WSEM"), 64); err == nil && v >= 0 {
		c.wSem = v
	}
	return c
}

// semanticReranker holds the embedder, fusion config, and a per-run cache of
// fact vectors. Fact ids are content-derived, so a vector is valid for the life
// of the fact; the cache makes an eval over many queries embed each fact at
// most once.
type semanticReranker struct {
	e     Embedder
	cfg   fusionConfig
	cache map[string][]float32
}

// newSemanticReranker returns nil when no embedder is available, so callers can
// pass the result straight to rankFactsFused and get the pure-lexical path.
func newSemanticReranker(e Embedder) *semanticReranker {
	if e == nil {
		return nil
	}
	return &semanticReranker{e: e, cfg: defaultFusionConfig(), cache: map[string][]float32{}}
}

