121			if fused[ia] != fused[ib] {
122				return fused[ia] > fused[ib]
123			}
124			return cands[ia].rec.UpdatedAt.After(cands[ib].rec.UpdatedAt)
125		})
126		if len(order) > limit {
127			order = order[:limit]
128		}
129		out := make([]factRecord, len(order))
130		for i, idx := range order {
131			out[i] = cands[idx].rec
132		}
133		return out
134	}
135	
136	// cosineFloat32 is the cosine similarity of two vectors. Vectors from the
137	// static embedder are already unit length, but guarding the norms keeps it
138	// correct for the zero vector (empty/all-unknown text) — which yields 0.
139	func cosineFloat32(a, b []float32) float64 {
140		if len(a) != len(b) {
141			return 0
142		}
143		var dot, na, nb float64
144		for i := range a {
145			dot += float64(a[i]) * float64(b[i])
146			na += float64(a[i]) * float64(a[i])
147			nb += float64(b[i]) * float64(b[i])
148		}
149		if na == 0 || nb == 0 {
150			return 0
151		}
152		return dot / (math.Sqrt(na) * math.Sqrt(nb))
153	}

