// printFactLine renders a fact for human-readable listings.
func printFactLine(cmd *cobra.Command, f factRecord) {
	marker := ""
	switch f.Status {
	case factStatusSuperseded:
		marker = " (superseded)"
	case factStatusRetracted:
		marker = " (retracted)"
	}
